# =============================================================================
# History
# =============================================================================

[history]
persistence = "save-all"
retention_days = 90
audit_log = true

# =============================================================================
# Shell Environment
# =============================================================================

[shell_environment_policy]
inherit = "core"
exclude = ["*_KEY", "*_SECRET", "*_TOKEN", "*_PASSWORD", "AWS_*", "AZURE_*"]

[sandbox_workspace_write]
writable_roots = []
network_access = true
exclude_slash_tmp = false

# =============================================================================
# Security (Enterprise)
# =============================================================================

[security]
input_validation = true
path_traversal_prevention = true
secret_scanning = true
cve_scanning = true
max_file_size = 10485760
blocked_patterns = ["\\\\.env$", "credentials\\\\.json$", "\\\\.pem$", "\\\\.key$", "secrets\\\\.yaml$"]

# RBAC configuration
[security.rbac]
enabled = true
default_role = "developer"

# Audit configuration
[security.audit]
enabled = true
destination = "file"
file_path = "./logs/audit.json"
retention_days = 90

# =============================================================================
# Performance
# =============================================================================

[performance]
max_agents = 8
task_timeout = 300
memory_limit = "1GB"
cache_enabled = true
cache_ttl = 3600
parallel_execution = true

# =============================================================================
# Logging (Enterprise)
# =============================================================================

[logging]
level = "info"
format = "json"
destination = "both"
file_path = "./logs/claude-flow.log"
max_files = 30
max_size = "50MB"

# =============================================================================
# Neural Intelligence
# =============================================================================

[neural]
sona_enabled = true
hnsw_enabled = true
hnsw_m = 16
hnsw_ef_construction = 200
hnsw_ef_search = 100
pattern_learning = true
learning_rate = 0.01

# =============================================================================
# Swarm Orchestration
# =============================================================================

[swarm]
default_topology = "hierarchical"
default_strategy = "specialized"
consensus = "raft"
anti_drift = true
checkpoint_interval = 10

# =============================================================================
# Hooks
# =============================================================================

[hooks]
enabled = true
pre_task = true
post_task = true
train_on_edit = true

# =============================================================================
# Background Workers
# =============================================================================

[workers]
enabled = true

[workers.audit]
enabled = true
priority = "critical"
interval = 300

[workers.optimize]
enabled = true
priority = "high"
interval = 600

[workers.consolidate]
enabled = true
priority = "low"
interval = 1800

[workers.testgaps]
enabled = true
priority = "normal"
interval = 3600

# =============================================================================
# Compliance
# =============================================================================

[compliance]
soc2 = true
gdpr = true
pci_dss = false
hipaa = false
`;
}

