 */

import type { ValidationResult, ValidationError, ValidationWarning } from '../types.js';

/**
 * TOML parsing result
 */
interface TomlParseResult {
  valid: boolean;
  errors: Array<{ line: number; message: string }>;
  data: Record<string, unknown>;
}

